/* ===================== BÀI 8 · Clock và số chu kỳ của lệnh ===================== */
/* Bài 8 · Clock và số chu kỳ của lệnh (AMTS-EMB-001-M02-L04, MC51-008) — sinh bởi tools/author/mcu8051/l08.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR8=[{"label":"Ví dụ: Cộng chu kỳ máy của từng lệnh","code":"; Ví dụ 1: cộng số chu kỳ máy của từng lệnh\n        ORG     0000H\n        MOV     A,#12H                  ; 2 byte · 1 chu kỳ\n        MOV     R0,#30H                 ; 2 byte · 1 chu kỳ\n        MOV     @R0,A                   ; 1 byte · 1 chu kỳ\n        MOV     31H,#34H                ; 3 byte · 2 chu kỳ\n        INC     DPTR                    ; 1 byte · 2 chu kỳ\n        MOV     B,#3                    ; 3 byte · 2 chu kỳ\n        MUL     AB                      ; 1 byte · 4 chu kỳ\n        SJMP    $\n        END\n","note":"Bấm Từng bước và cộng dần: 1, 2, 3, 5, 7, 9, 13 chu kỳ. INC DPTR chỉ 1 byte nhưng 2 chu kỳ; MUL AB 1 byte nhưng 4 chu kỳ. 13 chu kỳ = 13 µs ở 12 MHz (đổi Thạch anh sang 11,0592 MHz: ≈ 14,11 µs).","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Hai vòng DJNZ lồng nhau, 1 ms ở 12 MHz","code":"; Ví dụ 2: trễ bằng hai vòng DJNZ lồng nhau, 12 MHz\n        ORG     0000H\n        MOV     R7,#2                   ; 1 chu kỳ\nNGOAI:  MOV     R6,#248                 ; 1 chu kỳ, chạy 2 lần\nTRONG:  DJNZ    R6,TRONG                ; 2 chu kỳ, chạy 2 x 248 lần\n        DJNZ    R7,NGOAI                ; 2 chu kỳ, chạy 2 lần\n        CPL     P1.0                    ; 1 chu kỳ: hết thời gian trễ\n        SJMP    $\n        END\n","note":"Theo công thức N = 1 + n1(2 × n2 + 3) = 1 + 2 × 499 = 999 chu kỳ, cộng CPL P1.0 là 1000. Bấm Chạy: Kết quả ghi 1002 chu kỳ (thêm 2 của SJMP $), P1.0 đổi mức đúng ở 1000 µs.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Cùng vòng lặp ở thạch anh 11,0592 MHz","code":"; Ví dụ 3: cùng chương trình, thạch anh 11,0592 MHz\n        ORG     0000H\n        MOV     R7,#2\nNGOAI:  MOV     R6,#248\nTRONG:  DJNZ    R6,TRONG\n        DJNZ    R7,NGOAI\n        CPL     P1.0                    ; còn đúng 1 ms không?\n        SJMP    $\n        END\n","note":"Chương trình giống hệt ví dụ 2, thạch anh 11,0592 MHz: vẫn 1000 chu kỳ máy nhưng mỗi chu kỳ ≈ 1,0851 µs, nên LED đổi ở ≈ 1085,07 µs, chậm hơn 8,5 %.","dev":{"led":true},"fosc":11059200},{"label":"Sửa: Tính lại số lặp cho 11,0592 MHz","code":"; Sửa: tính lại số lặp cho thạch anh 11,0592 MHz\n; 1 ms / 1,0851 us = 921,6 chu kỳ máy cần có\n        ORG     0000H\n        MOV     R7,#2\nNGOAI:  MOV     R6,#228                 ; 1 + 2 x (2 x 228 + 3) + 1 = 920\nTRONG:  DJNZ    R6,TRONG\n        DJNZ    R7,NGOAI\n        CPL     P1.0\n        SJMP    $\n        END\n","note":"Cần N ≈ 1 ms × 11 059 200 / 12 = 921,6. Giữ n1 = 2, chọn n2 = 228: N = 2 + 2 × 459 = 920 chu kỳ ≈ 998,26 µs, sai số −0,17 %.","dev":{"led":true},"fosc":11059200},{"label":"Ví dụ: Chọn lệnh 1 chu kỳ thay lệnh 2 chu kỳ","code":"; Ví dụ 5: cùng kết quả, ít chu kỳ hơn\n        ORG     0000H\n; Đoạn 1: MOV direct,#data, 2 chu kỳ mỗi lệnh\n        MOV     30H,#55H\n        MOV     31H,#55H\n        MOV     32H,#55H\n        MOV     33H,#55H\n; Đoạn 2: nạp A một lần, MOV direct,A 1 chu kỳ\n        MOV     A,#55H\n        MOV     34H,A\n        MOV     35H,A\n        MOV     36H,A\n        MOV     37H,A\n        SJMP    $\n        END\n","note":"Đoạn 1: bốn lệnh MOV direct,#data, mỗi lệnh 3 byte, 2 chu kỳ: 8 chu kỳ. Đoạn 2: MOV A,#55H rồi bốn lệnh MOV direct,A (2 byte, 1 chu kỳ): 5 chu kỳ. Cùng kết quả, ít hơn 3 chu kỳ và 2 byte (12 byte so với 10 byte).","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: R6 = 0 làm DJNZ lặp 256 lần","code":"; Bẫy: R6 = 0 không có nghĩa là không lặp\n        ORG     0000H\n        MOV     R6,#0                   ; tưởng là bỏ qua vòng lặp\nLAP:    DJNZ    R6,LAP                  ; 00H - 1 = FFH: còn lặp tiếp\n        CPL     P1.0\n        SJMP    $\n        END\n","note":"MOV R6,#0 không bỏ qua vòng lặp: DJNZ giảm 00H thành FFH rồi lặp tiếp, tổng 256 lần. Đoán trước: tổng chu kỳ tới SJMP $? (1 + 512 + 1 = 514.)","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Số lặp 300 không vừa 8 bit","code":"; Lỗi: số lặp không vừa một thanh ghi 8 bit\n        ORG     0000H\n        MOV     R6,#300                 ; muốn lặp 300 lần\nLAP:    DJNZ    R6,LAP\n        SJMP    $\n        END\n","note":"Trình dịch báo lỗi dòng 3: 300 không vừa 8 bit. Lưu ý: sdas8051 (bộ SDCC) không báo lỗi mà cắt còn 2CH = 44 lần lặp; trễ sai mà không có thông báo nào. Sửa bằng hai vòng lồng (ví dụ 2).","dev":{"led":true},"fosc":12000000}];
const sim8=makeSim51(document.getElementById("m51-l8"),{id:"s8",presets:PR8,ram:256});
makeEx51(document.getElementById("ex-l8"),"l8",[{"t":"Chép một byte trong 7 chu kỳ","d":"<p>Chép giá trị của ô <code>40H<\/code> vào bốn ô <code>30H<\/code>–<code>33H<\/code>. Ô <code>40H<\/code> giữ nguyên. Code mẫu đúng kết quả nhưng chạy 10 chu kỳ máy; sửa để chạy không quá <b>7 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>).<\/p><p>Ví dụ: <code>40H = A5H<\/code> → <code>30H..33H = A5H A5H A5H A5H<\/code>.<\/p>","start":"        ORG     0000H\n; Đúng kết quả nhưng 10 chu kỳ máy\n        MOV     30H,40H\n        MOV     31H,40H\n        MOV     32H,40H\n        MOV     33H,40H\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":165,"0x30":238,"0x31":237,"0x32":236,"0x33":235}},"expect":{"iram":{"0x40":165,"0x30":165,"0x31":165,"0x32":165,"0x33":165}}},{"setup":{"iram":{"0x40":0,"0x30":238,"0x31":237,"0x32":236,"0x33":235}},"expect":{"iram":{"0x40":0,"0x30":0,"0x31":0,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x40":255,"0x30":238,"0x31":237,"0x32":236,"0x33":235}},"expect":{"iram":{"0x40":255,"0x30":255,"0x31":255,"0x32":255,"0x33":255}}},{"setup":{"iram":{"0x40":1,"0x30":238,"0x31":237,"0x32":236,"0x33":235}},"expect":{"iram":{"0x40":1,"0x30":1,"0x31":1,"0x32":1,"0x33":1}}},{"setup":{"iram":{"0x40":128,"0x30":238,"0x31":237,"0x32":236,"0x33":235}},"expect":{"iram":{"0x40":128,"0x30":128,"0x31":128,"0x32":128,"0x33":128}}},{"setup":{"iram":{"0x40":60,"0x30":238,"0x31":237,"0x32":236,"0x33":235}},"expect":{"iram":{"0x40":60,"0x30":60,"0x31":60,"0x32":60,"0x33":60}}}],"maxCyc":7},"hints":["Tra số chu kỳ: MOV direct,direct tốn 2 chu kỳ. Lệnh MOV nào ghi vào địa chỉ trực tiếp chỉ tốn 1 chu kỳ?","MOV direct,A tốn 1 chu kỳ; muốn dùng nó thì giá trị phải nằm sẵn trong A.","Đưa 40H vào A một lần; sau đó mỗi lần ghi A ra một ô chỉ tốn 1 chu kỳ. Cộng lại xem có đủ 7 chu kỳ không (tính cả SJMP $)."],"why":"MOV direct,direct (85H) dài 3 byte, 2 chu kỳ. Đưa giá trị vào A một lần (MOV A,direct: 1 chu kỳ) rồi dùng MOV direct,A (1 chu kỳ) bốn lần: 1 + 4 + 2 = 7 chu kỳ thay vì 4 × 2 + 2 = 10. Cùng kết quả, số chu kỳ phụ thuộc vào cách chọn lệnh."},{"t":"Đếm chu kỳ của vòng DJNZ","d":"<p>Đoạn trễ <code>MOV R7,30H<\/code> rồi <code>LAP: DJNZ R7,LAP<\/code> chạy bao nhiêu chu kỳ máy? Ô <code>30H<\/code> chứa giá trị nạp vào R7 (00H–FFH). Ghi tổng số chu kỳ máy của hai lệnh, dạng số 16 bit, vào <code>31H<\/code> (byte cao) và <code>32H<\/code> (byte thấp). Biết <code>MOV Rn,direct<\/code> tốn 2 chu kỳ, <code>DJNZ<\/code> tốn 2 chu kỳ. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 0AH<\/code> → 2 + 2 × 10 = 22 chu kỳ → <code>31H = 00H<\/code>, <code>32H = 16H<\/code>.<\/p>","start":"        ORG     0000H\n; Đúng khi 30H nhỏ, sai ở các giá trị biên\n        MOV     A,30H\n        ADD     A,30H                   ; 2n (bỏ mất phần nhớ)\n        ADD     A,#2                    ; + 2 của MOV R7,30H\n        MOV     32H,A\n        MOV     31H,#0\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":10,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":10,"0x31":0,"0x32":22}}},{"setup":{"iram":{"0x30":1,"0x31":238,"0x32":238},"regs":{"PSW":128}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":4}}},{"setup":{"iram":{"0x30":0,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":2,"0x32":2}}},{"setup":{"iram":{"0x30":255,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":2,"0x32":0}}},{"setup":{"iram":{"0x30":127,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":127,"0x31":1,"0x32":0}}},{"setup":{"iram":{"0x30":128,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":128,"0x31":1,"0x32":2}}},{"setup":{"iram":{"0x30":200,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":200,"0x31":1,"0x32":146}}}]},"hints":["Tổng = 2 + 2 × (số lần DJNZ chạy) = 2 × (số lần + 1). Với 30H = 00H, DJNZ chạy bao nhiêu lần (ví dụ 6)?","Số lần + 1 có thể vượt FFH (với 30H = FFH và 30H = 00H): cần giữ byte cao riêng. Sau INC A, giá trị 8 bit nhỏ hơn 2 đúng ở hai trường hợp đó.","Nhân 2 một số 16 bit: cộng byte thấp với chính nó (ADD), rồi cộng byte cao với chính nó kèm cờ nhớ (ADDC)."],"why":"DJNZ giảm trước rồi mới so với 0, nên R7 = 00H cho 256 lần lặp, không phải 0. Tổng = 2 + 2n với n = 1…256, tối đa 514 = 0202H, phải dùng 16 bit. Bộ thử 30H = 00H (514) và 30H = FFH (512) bắt hai lỗi hay gặp: coi 00H là 0 lần và quên byte cao."},{"t":"Xoay 4 byte trong 7 chu kỳ","d":"<p>Xoay vòng bốn ô <code>30H<\/code>–<code>33H<\/code> sang trái một vị trí: 30H nhận giá trị cũ của 31H, 31H nhận của 32H, 32H nhận của 33H, 33H nhận giá trị cũ của 30H. Code mẫu vừa sai kết quả vừa chậm. Sửa để đúng với mọi bộ thử, chạy không quá <b>7 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>12 byte<\/b>.<\/p><p>Ví dụ: <code>30H..33H = 11H 22H 33H 44H<\/code> → <code>22H 33H 44H 11H<\/code>.<\/p>","start":"        ORG     0000H\n; Sai kết quả và chậm: sửa cho đúng, <= 7 chu kỳ\n        MOV     30H,31H\n        MOV     31H,32H\n        MOV     32H,33H\n        MOV     A,30H\n        MOV     33H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":17,"0x31":34,"0x32":51,"0x33":68}},"expect":{"iram":{"0x30":34,"0x31":51,"0x32":68,"0x33":17}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":255,"0x31":0,"0x32":0,"0x33":0}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":255}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":3,"0x33":4}},"expect":{"iram":{"0x30":2,"0x31":3,"0x32":4,"0x33":1}}},{"setup":{"iram":{"0x30":165,"0x31":90,"0x32":165,"0x33":90}},"expect":{"iram":{"0x30":90,"0x31":165,"0x32":90,"0x33":165}}},{"setup":{"iram":{"0x30":128,"0x31":127,"0x32":1,"0x33":254}},"expect":{"iram":{"0x30":127,"0x31":1,"0x32":254,"0x33":128}}}],"maxCyc":7,"maxBytes":12},"hints":["Chạy code mẫu từng bước: giá trị cũ của 30H mất ở lệnh nào? MOV direct,direct tốn mấy chu kỳ?","XCH A,direct (1 byte mã lệnh + 1 byte địa chỉ, 1 chu kỳ) đổi chỗ A với một ô: vừa ghi giá trị mới, vừa lấy giá trị cũ ra A.","Mỗi XCH vừa ghi giá trị mới vừa lấy giá trị cũ ra A. Đi theo chiều nào (tới hay lùi) thì giá trị cuối cùng trong A rơi đúng vào 30H?"],"why":"Code mẫu ghi đè 30H trước khi cất giá trị cũ, nên 33H nhận sai giá trị; ba lệnh MOV direct,direct tốn 2 chu kỳ mỗi lệnh: tổng 10 chu kỳ, 15 byte. Với XCH, mỗi bước vừa ghi vừa lấy giá trị cũ trong 1 chu kỳ: MOV A,30H, ba lệnh XCH, MOV 30H,A = 5 chu kỳ + 2 của SJMP $ = 7 chu kỳ, 12 byte."}]);

makeQuiz("quiz8","score8",[{"q": "Thạch anh 12 MHz, lõi 12 nhịp. Một lệnh DJNZ (2 chu kỳ máy) chạy mất bao lâu?", "o": ["2 µs", "≈ 0,167 µs", "24 µs", "1 µs"], "a": 0, "e": "Một chu kỳ máy = 12 / 12 MHz = 1 µs, nên 2 chu kỳ = 2 µs. 0,167 µs là 2 chu kỳ dao động (quên nhân 12); 24 µs là nhân 12 hai lần."}, {"q": "Đoạn MOV R7,#2 / N1: MOV R6,#248 / N2: DJNZ R6,N2 / DJNZ R7,N1 tốn bao nhiêu chu kỳ máy?", "o": ["992", "995", "1 998", "999"], "a": 3, "e": "Mỗi vòng ngoài: 1 (MOV R6) + 2 × 248 (DJNZ trong) + 2 (DJNZ ngoài) = 499; hai vòng là 998, cộng 1 của MOV R7 là 999. 992 chỉ đếm vòng trong, 995 quên DJNZ ngoài."}, {"q": "Sau MOV R6,#0, lệnh LAP: DJNZ R6,LAP chạy bao nhiêu lần?", "o": ["0 lần", "256 lần", "1 lần", "255 lần"], "a": 1, "e": "DJNZ giảm trước rồi mới so với 0: 00H − 1 = FFH ≠ 0 nên lặp tiếp, tới lần thứ 256 R6 mới về 00H. Nghĩ R6 = 0 là không lặp là lỗi hay gặp."}, {"q": "Lệnh nào dài 1 byte nhưng chạy 2 chu kỳ máy?", "o": ["INC DPTR", "MOV A,#05H", "MUL AB", "MOV 30H,#05H"], "a": 0, "e": "INC DPTR (A3) dài 1 byte, chạy 2 chu kỳ. MOV A,#05H dài 2 byte, chạy 1 chu kỳ; MUL AB dài 1 byte nhưng 4 chu kỳ; MOV 30H,#05H dài 3 byte, chạy 2 chu kỳ."}, {"q": "Một vòng trễ 1000 chu kỳ máy chạy 1 ms ở 12 MHz. Đổi sang thạch anh 11,0592 MHz, không sửa code, thời gian là bao nhiêu?", "o": ["1000 µs, không đổi", "≈ 921,6 µs, ngắn hơn", "≈ 1085 µs, dài hơn khoảng 8,5 %", "≈ 1085 ms"], "a": 2, "e": "Số chu kỳ không đổi, mỗi chu kỳ dài 12 / 11 059 200 s ≈ 1,0851 µs: 1000 × 1,0851 ≈ 1085 µs. 921,6 là số chu kỳ cần có cho 1 ms ở 11,0592 MHz, không phải thời gian."}]);

